<?php

declare(strict_types=1);

namespace Src;

/**
 * PageTranslator — dictionary-driven page translation for apps whose templates are not
 * wrapped in __() calls.
 *
 * In a layout's <head>:
 *     <html lang="{{ \Src\PageTranslator::htmlLang() }}">
 *     {!! \Src\PageTranslator::head() !!}
 *
 * Dictionaries live in <appRoot>/resources/lang/auto/<locale>.json (generated by
 * scripts/i18n/extract-strings.mjs + translate-strings.mjs). Human corrections go in
 * <appRoot>/resources/lang/auto/overrides.<locale>.json and always win.
 * English visitors get no extra payload at all.
 */
final class PageTranslator
{
    /** Locales translated by dictionary; English variants are served as-is. */
    private const TRANSLATED = ['fr', 'es'];

    /** @var array<string, array<string, string>> */
    private static array $cache = [];

    public static function appRoot(): string
    {
        // vendor/modernman00/shared-lib/src → app root
        $guess = dirname(__DIR__, 4);
        return is_dir($guess . '/resources') ? $guess : (string) getcwd();
    }

    public static function locale(): string
    {
        $loc = class_exists(I18n::class) ? I18n::getLocale() : 'en';
        return preg_match('/^[a-z]{2}$/', $loc) === 1 ? $loc : 'en';
    }

    /** Value for <html lang="…">. */
    public static function htmlLang(): string
    {
        $loc = self::locale();
        return $loc === 'us' ? 'en-US' : ($loc === 'en' ? 'en-GB' : $loc);
    }

    /**
     * @return array<string, string>
     */
    public static function dictionary(string $locale, ?string $appRoot = null): array
    {
        $root = $appRoot ?? self::appRoot();
        $key = $root . '|' . $locale;
        if (isset(self::$cache[$key])) {
            return self::$cache[$key];
        }
        $dict = [];
        foreach (["auto/{$locale}.json", "auto/overrides.{$locale}.json"] as $rel) {
            $file = $root . '/resources/lang/' . $rel;
            if (is_file($file)) {
                $data = json_decode((string) file_get_contents($file), true);
                if (is_array($data)) {
                    foreach ($data as $src => $tr) {
                        if (is_string($src) && is_string($tr) && $tr !== '') {
                            $dict[$src] = $tr;
                        }
                    }
                }
            }
        }
        return self::$cache[$key] = $dict;
    }

    /** Markup for <head>: empty for English; dictionary + translator for French/Spanish. */
    public static function head(?string $appRoot = null): string
    {
        $locale = self::locale();
        if (!in_array($locale, self::TRANSLATED, true)) {
            return '';
        }
        $dict = self::dictionary($locale, $appRoot);
        $js = __DIR__ . '/../resources/js/page-translator.js';
        if ($dict === [] || !is_file($js)) {
            return '';
        }
        $nonce = '';
        if (defined('CSP_NONCE')) {
            $n = (string) constant('CSP_NONCE');
            if (preg_match('/^[A-Za-z0-9+\/=_-]{8,128}$/', $n) === 1) {
                $nonce = ' nonce="' . htmlspecialchars($n, ENT_QUOTES, 'UTF-8') . '"';
            }
        }
        $payload = json_encode(['locale' => $locale, 'dict' => $dict], JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT);
        $code = str_ireplace('</script', '<\/script', (string) file_get_contents($js));

        return '<style' . $nonce . '>html.atg-i18n-pending body{visibility:hidden}</style>'
            . '<script' . $nonce . '>document.documentElement.classList.add("atg-i18n-pending");'
            . 'window.__ATG_I18N__=' . ($payload ?: '{}') . ';' . $code . '</script>';
    }
}
